// Sponsor and alumni logos: white silhouettes generated by `npm run images` from
// assets-src/logos/. `w`/`h` are the generated image's pixel size; `scale` nudges
// logos whose thin strokes read small at the shared size.
const files = import.meta.glob('./assets/logos/*.webp', { eager: true, import: 'default' });
const src = (name) => files[`./assets/logos/${name}.webp`];

const logo = (file, name, w, h, scale = 1) => ({ name, src: src(file), w, h, scale });

export const CURRENT_SPONSORS = [
  logo('nnl', 'Naval Nuclear Laboratory', 353, 160),
  logo('whimsy', 'Whimsy Tech', 215, 160),
  logo('reng', 'Rutgers Engineering', 223, 160),
];

